-- 文件作用说明：建立欢迎语、个人公共话术、关键词回复、留言评价、通知偏好及可靠自动回复任务。
CREATE TABLE chat_settings(tenant_id uuid PRIMARY KEY REFERENCES tenants(id),settings jsonb NOT NULL DEFAULT '{"welcome_enabled":true,"welcome_text":"您好，请问有什么可以帮助您？","welcome_delay_seconds":0,"keywords_enabled":true,"typing_enabled":true}',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE quick_replies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),owner_membership_id uuid,title text NOT NULL,content text NOT NULL,shortcut text NOT NULL DEFAULT '',category text NOT NULL DEFAULT '',enabled boolean NOT NULL DEFAULT true,sort integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,owner_membership_id) REFERENCES tenant_memberships(tenant_id,id));
CREATE TABLE keyword_rules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),name text NOT NULL,match_mode text NOT NULL CHECK(match_mode IN('contains','exact')),pattern text NOT NULL,reply text NOT NULL,priority integer NOT NULL DEFAULT 0,cooldown_seconds integer NOT NULL DEFAULT 60 CHECK(cooldown_seconds BETWEEN 0 AND 86400),enabled boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id));
CREATE TABLE offline_leads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),contact_id uuid NOT NULL,access_link_id uuid NOT NULL,conversation_id uuid,client_request_id uuid NOT NULL,display_name text NOT NULL DEFAULT '',phone text NOT NULL DEFAULT '',content text NOT NULL,status text NOT NULL DEFAULT 'new' CHECK(status IN('new','following','resolved')),notes text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,contact_id,client_request_id),FOREIGN KEY(tenant_id,contact_id) REFERENCES contacts(tenant_id,id),FOREIGN KEY(tenant_id,access_link_id) REFERENCES access_links(tenant_id,id),FOREIGN KEY(tenant_id,conversation_id) REFERENCES conversations(tenant_id,id));
CREATE TABLE conversation_evaluations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,conversation_id uuid NOT NULL,contact_id uuid NOT NULL,score integer NOT NULL CHECK(score BETWEEN 1 AND 5),comment text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,conversation_id),FOREIGN KEY(tenant_id,conversation_id) REFERENCES conversations(tenant_id,id),FOREIGN KEY(tenant_id,contact_id) REFERENCES contacts(tenant_id,id));
CREATE TABLE notification_preferences(tenant_id uuid NOT NULL,membership_id uuid NOT NULL,settings jsonb NOT NULL DEFAULT '{"sound_enabled":true,"speech_enabled":false,"system_enabled":false,"content_preview":false,"muted":false,"volume":0.7}',updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,membership_id),FOREIGN KEY(tenant_id,membership_id) REFERENCES tenant_memberships(tenant_id,id));
CREATE TABLE chat_operation_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,conversation_id uuid NOT NULL,job_type text NOT NULL CHECK(job_type IN('welcome','keyword')),trigger_key text NOT NULL,rule_id uuid,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'queued' CHECK(status IN('queued','completed','cancelled','failed')),run_after timestamptz NOT NULL DEFAULT now(),attempts integer NOT NULL DEFAULT 0,completed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,trigger_key),FOREIGN KEY(tenant_id,conversation_id) REFERENCES conversations(tenant_id,id),FOREIGN KEY(tenant_id,rule_id) REFERENCES keyword_rules(tenant_id,id));
CREATE INDEX pending_chat_operation_jobs ON chat_operation_jobs(tenant_id,run_after) WHERE status='queued';
CREATE TABLE chat_audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,actor_id uuid,action text NOT NULL,target_id uuid,payload jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
DO $$ DECLARE t text; a record; d jsonb := '{"id":"主键编号","tenant_id":"所属租户编号","settings":"经过类型校验的配置或偏好","updated_at":"最近修改时间","owner_membership_id":"个人话术所属成员，空值表示公共话术","title":"话术标题","content":"纯文本内容","shortcut":"快捷检索代码","category":"话术分类名称","enabled":"是否允许新触发","sort":"显示排序","created_at":"创建时间","name":"规则名称","match_mode":"完全或包含匹配模式","pattern":"纯文本匹配关键词","reply":"自动回复的纯文本内容","priority":"规则命中优先级","cooldown_seconds":"同会话规则触发冷却秒数","contact_id":"客户编号","access_link_id":"来源接入链接编号","conversation_id":"关联的独立咨询编号","client_request_id":"客户端稳定请求去重编号","display_name":"留言时姓名快照","phone":"留言时未验证联系电话","status":"处理或执行状态","notes":"授权成员跟进备注","score":"一至五星满意度评分","comment":"访客评价文字","membership_id":"偏好所属租户成员","job_type":"欢迎语或关键词任务种类","trigger_key":"任务触发唯一幂等键","rule_id":"关联关键词规则编号","payload":"不含凭证的系统消息任务载荷","run_after":"允许执行时间","attempts":"执行尝试次数","completed_at":"完成或取消时间","actor_id":"操作参与者编号","action":"受审计的操作类型","target_id":"操作目标编号"}'::jsonb; BEGIN
FOREACH t IN ARRAY ARRAY['chat_settings','quick_replies','keyword_rules','offline_leads','conversation_evaluations','notification_preferences','chat_operation_jobs','chat_audit_logs'] LOOP
EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id = nullif(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK (tenant_id = nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',t);
FOR a IN SELECT attname FROM pg_attribute WHERE attrelid=('public.'||t)::regclass AND attnum>0 AND NOT attisdropped LOOP IF NOT d ? a.attname THEN RAISE EXCEPTION '字段缺少中文注释：%.%',t,a.attname; END IF; EXECUTE format('COMMENT ON COLUMN %I.%I IS %L',t,a.attname,d->>a.attname); END LOOP; END LOOP; END $$;
COMMENT ON TABLE chat_settings IS '租户欢迎语和接待效率配置'; COMMENT ON TABLE quick_replies IS '租户公共及成员个人快捷话术'; COMMENT ON TABLE keyword_rules IS '仅处理访客新文字的关键词自动回复规则'; COMMENT ON TABLE offline_leads IS '保留客户及咨询关联的离线留言'; COMMENT ON TABLE conversation_evaluations IS '咨询结束后的访客真实评价'; COMMENT ON TABLE notification_preferences IS '每租户成员的跨设备通知偏好'; COMMENT ON TABLE chat_operation_jobs IS '与咨询消息事务一致的持久系统回复任务'; COMMENT ON TABLE chat_audit_logs IS '接待运营配置和客户操作审计';
